import dayjs from "dayjs";
import { getTimeZones } from "@vvo/tzdb";
import { localeDirection, currentLocale } from "./i18n";
import { POSITION } from "vue-toastification";

/**
 * Returns the offset from UTC in hours for the current locale.
 * @param {string} timeZone Timezone to get offset for
 * @returns {number} The offset from UTC in hours.
 *
 * Generated by Trelent
 */
function getTimezoneOffset(timeZone) {
    const now = new Date();
    const tzString = now.toLocaleString("en-US", {
        timeZone,
    });
    const localString = now.toLocaleString("en-US");
    const diff = (Date.parse(localString) - Date.parse(tzString)) / 3600000;
    const offset = diff + now.getTimezoneOffset() / 60;
    return -offset;
}

/**
 * Returns a list of timezones sorted by their offset from UTC.
 * @returns {object[]} A list of the given timezones sorted by their offset from UTC.
 *
 * Generated by Trelent
 */
export function timezoneList() {
    let result = [];
    const timeZones = getTimeZones();

    for (let timezone of timeZones) {
        try {
            let display = dayjs().tz(timezone.name).format("Z");

            result.push({
                name: `(UTC${display}) ${timezone.name}`,
                value: timezone.name,
                time: getTimezoneOffset(timezone.name),
            });
        } catch (e) {
            // Skipping not supported timezone.name by dayjs
        }
    }

    result.sort((a, b) => {
        if (a.time > b.time) {
            return 1;
        }

        if (b.time > a.time) {
            return -1;
        }

        return 0;
    });

    return result;
}

/**
 * Set the locale of the HTML page
 * @returns {void}
 */
export function setPageLocale() {
    const html = document.documentElement;
    html.setAttribute("lang", currentLocale() );
    html.setAttribute("dir", localeDirection() );
}

/**
 * Get the base URL
 * Mainly used for dev, because the backend and the frontend are in different ports.
 * @returns {string} Base URL
 */
export function getResBaseURL() {
    const env = process.env.NODE_ENV;
    if (env === "development" && isDevContainer()) {
        return location.protocol + "//" + getDevContainerServerHostname();
    } else if (env === "development" || localStorage.dev === "dev") {
        return location.protocol + "//" + location.hostname + ":3001";
    } else {
        return "";
    }
}

/**
 * Are we currently running in a dev container?
 * @returns {boolean} Running in dev container?
 */
export function isDevContainer() {
    // eslint-disable-next-line no-undef
    return (typeof DEVCONTAINER === "string" && DEVCONTAINER === "1");
}

/**
 * Supports GitHub Codespaces only currently
 * @returns {string} Dev container server hostname
 */
export function getDevContainerServerHostname() {
    if (!isDevContainer()) {
        return "";
    }

    // eslint-disable-next-line no-undef
    return CODESPACE_NAME + "-3001." + GITHUB_CODESPACES_PORT_FORWARDING_DOMAIN;
}

/**
 * Regex pattern for identifying hostnames and IP addresses
 * @returns {RegExp} The requested regex
 */
export function hostNameRegexPattern() {
    const ipRegexPattern =
        /((^(([0-9]{1,3}\.){3}[0-9]{1,3})$)|(^((([0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4})$)))/.source;
    const hostNameRegexPattern =
        /^([a-zA-Z0-9])?(([a-zA-Z0-9_]|[a-zA-Z0-9_][a-zA-Z0-9_\-]*[a-zA-Z0-9_])\.)*([A-Za-z0-9_]|[A-Za-z0-9_][A-Za-z0-9_\-]*[A-Za-z0-9_])(\.)?$/.source;
    return `${ipRegexPattern}|${hostNameRegexPattern}`;
}

/**
 * Get the tag color options
 * Shared between components
 * @param {any} self Component
 * @returns {object[]} Colour options
 */
export function colorOptions(self) {
    return [
        { name: self.$t("Gray"),
            color: "#4B5563" },
        { name: self.$t("Red"),
            color: "#DC2626" },
        { name: self.$t("Orange"),
            color: "#D97706" },
        { name: self.$t("Green"),
            color: "#059669" },
        { name: self.$t("Blue"),
            color: "#2563EB" },
        { name: self.$t("Indigo"),
            color: "#4F46E5" },
        { name: self.$t("Purple"),
            color: "#7C3AED" },
        { name: self.$t("Pink"),
            color: "#DB2777" },
    ];
}

/**
 * Loads the toast timeout settings from storage.
 * @returns {object} The toast plugin options object.
 */
export function loadToastSettings() {
    return {
        position: POSITION.BOTTOM_RIGHT,
        containerClassName: "toast-container mb-5",
        showCloseButtonOnHover: true,

        filterBeforeCreate: (toast, toasts) => {
            if (toast.timeout === 0) {
                return false;
            } else {
                return toast;
            }
        },
    };
}

/**
 * Get timeout for success toasts
 * @returns {(number|boolean)} Timeout in ms. If false timeout disabled.
 */
export function getToastSuccessTimeout() {
    let successTimeout = 20000;

    if (localStorage.toastSuccessTimeout !== undefined) {
        const parsedTimeout = parseInt(localStorage.toastSuccessTimeout);
        if (parsedTimeout != null && !Number.isNaN(parsedTimeout)) {
            successTimeout = parsedTimeout;
        }
    }

    if (successTimeout === -1) {
        successTimeout = false;
    }

    return successTimeout;
}

/**
 * Get timeout for error toasts
 * @returns {(number|boolean)} Timeout in ms. If false timeout disabled.
 */
export function getToastErrorTimeout() {
    let errorTimeout = -1;

    if (localStorage.toastErrorTimeout !== undefined) {
        const parsedTimeout = parseInt(localStorage.toastErrorTimeout);
        if (parsedTimeout != null && !Number.isNaN(parsedTimeout)) {
            errorTimeout = parsedTimeout;
        }
    }

    if (errorTimeout === -1) {
        errorTimeout = false;
    }

    return errorTimeout;
}

// Maps the bare exception class names that bubble up through
// server/monitor_types/utils.py::exception_message() to short, human phrases.
// Unknown values pass through unchanged, so real error strings
// ("HTTP 503", "All connection attempts failed", DNS results, etc.) are
// rendered as-is.
const STATUS_MESSAGE_HUMANIZATIONS = {
    ReadTimeout: "Read timeout — server didn't respond in time",
    ConnectTimeout: "Connection timed out",
    WriteTimeout: "Write timeout",
    PoolTimeout: "Connection pool timeout",
    ConnectError: "Could not connect",
    ReadError: "Connection dropped while reading",
    WriteError: "Connection dropped while writing",
    RemoteProtocolError: "Server returned a malformed response",
    LocalProtocolError: "Malformed request",
    UnsupportedProtocol: "Unsupported protocol",
    ProxyError: "Proxy error",
    DecodingError: "Could not decode response",
    TooManyRedirects: "Too many redirects",
    TimeoutError: "Operation timed out",
    CancelledError: "Probe was cancelled",
    ConnectionRefusedError: "Connection refused",
    ConnectionResetError: "Connection reset",
    ConnectionAbortedError: "Connection aborted",
    BrokenPipeError: "Connection closed before response",
    ServerSelectionTimeoutError: "Could not reach a database server",
    NetworkTimeout: "Network timeout",
    AutoReconnect: "Database connection lost",
    OperationFailure: "Database operation failed",
    Timeout: "Timed out",
};

/**
 * Humanize a heartbeat/incident `msg` value for display.
 *
 * The backend stores either a real error string or, when an exception's
 * `str()` is empty, the bare class name (see server/monitor_types/utils.py).
 * The latter case yields jargon like "ReadTimeout"; this util relabels the
 * known class names with a short human phrase and passes everything else
 * through untouched.
 * @param {string|null|undefined} msg Raw message from heartbeat / incident
 * @returns {string} Humanized message (or the original if unmapped/empty)
 */
export function humanizeStatusMessage(msg) {
    if (msg == null) {
        return "";
    }
    const trimmed = String(msg).trim();
    if (!trimmed) {
        return "";
    }
    return STATUS_MESSAGE_HUMANIZATIONS[trimmed] || trimmed;
}
